LEVELS={'T':'task_outcome','S':'software_action_failure','O':'recorded_override_state','P':'specific_physical_cause','L':'limitation'}
assert len(texts)==96 and set(spec)==set(range(96))
inventories={}
for n,text in enumerate(texts):
 sentences=re.split(r'(?<=[.!?])\s+(?=[A-Z])',text)
 assert len(sentences)==len(spec[n]),(n,sentences,spec[n])
 atoms=[]
 for span,props in zip(sentences,spec[n]):
  assert span in text
  for prop in props.split('|'):
   level,statement=prop.split(' ',1)
   atoms.append({'statement':statement+'.','response_span':span,'asserted_abstraction_level':LEVELS[level]})
 inventories[text]=atoms
out=[]
for response in bank['items']:
 rid=response['response_id'];text=response['response_text'];atoms=[]
 for n,atom in enumerate(inventories[text],1):
  atoms.append({'item_id':f'{rid}-a{n:03d}',**atom})
 out.append({'response_id':rid,'response_text_sha256':hashlib.sha256(text.encode('utf-8')).hexdigest(),'atoms':atoms})
result={'schema':'hexar-developer-atomic-inventory/v1','atomization_route':'method-blind developer inventory, not qualified model atomizer','source_bank_sha256':hashlib.sha256((ROOT/'blind_bank.json').read_bytes()).hexdigest(),'items':out}
(ROOT/'atomic_inventory.json').write_text(json.dumps(result,indent=2,sort_keys=True)+'\n')
print(json.dumps({'responses':len(out),'unique_texts':len(texts),'atoms':sum(len(x['atoms']) for x in out),'unique_text_atoms':sum(len(x) for x in inventories.values())}))
